--
-- Generated by make-patch.py. The client gets the class row and the skill
-- rows in patch-enUS-4.MPQ; editing one without the other desynchronises
-- them. The class is the game masters' own: see GM_CLASS_ID there, and
-- `.gmclass` in mod-sanctuary-gm, which is the only way a character gets it.
--

DELETE FROM `chrclasses_dbc` WHERE `ID` = 10;


DELETE FROM `skillraceclassinfo_dbc` WHERE `ClassMask` = 512;


DELETE FROM `playercreateinfo` WHERE `class` = 10;

SELECT p.`race`, 10, p.`map`, p.`zone`, p.`position_x`, p.`position_y`, p.`position_z`, p.`orientation`
FROM `playercreateinfo` p
JOIN (SELECT `race`, MIN(`class`) AS `class` FROM `playercreateinfo` WHERE `class` NOT IN (6, 10) GROUP BY `race`) starter
  ON starter.`race` = p.`race` AND starter.`class` = p.`class`;

DELETE FROM `player_class_stats` WHERE `Class` = 10;

SELECT 10, `Level`, `BaseHP`, `BaseMana`, `Strength`, `Agility`, `Stamina`, `Intellect`, `Spirit`
FROM (SELECT * FROM `player_class_stats` WHERE `Class` = 2) donor;
